  // (a) x1..x30 are reloaded via ld in the Program Buffer. x31 is NOT loaded via
  //     ld (its scratch slot is the guard word the guest cannot read).
  int found = 0;
  for (uint8_t k = 1; k < 31; ++k)
    if (in_progbuf(hybrid::encode_ld(k, 31, static_cast<int32_t>((k - 1) * 8))))
      ++found;
  CHECK(found == 30);
  CHECK(!in_progbuf(hybrid::encode_ld(31, 31, 30 * 8)));  // no ld for x31

  // (b) exactly TWO GPR abstract writes to x31: first seeds the base with the
  //     scratch GPA, last restores x31's architectural value. No other GPR uses
  //     an abstract write (x1..x30 come via ld).
  const uint64_t gpr_gpa = hybrid::gpr_scratch_gpa(kScratch);
  std::vector<uint64_t> x31_writes;
  int nonx31_gpr_writes = 0;
  for (std::size_t i = 2; i < bus.ops.size(); ++i) {
    const auto& op = bus.ops[i];
    if (op.kind != DmiOp::Kind::Write || op.reg != kCommand) continue;
    const uint16_t rn = static_cast<uint16_t>(op.value & 0xFFFFu);
    if (!((op.value >> 16) & 1u)) continue;
    if (rn == hybrid::regno_gpr(31))
      x31_writes.push_back((uint64_t(bus.ops[i - 1].value) << 32)
                           | bus.ops[i - 2].value);
    else if (rn > hybrid::regno_gpr(0) && rn <= hybrid::regno_gpr(30))
      ++nonx31_gpr_writes;
  }
  REQUIRE(x31_writes.size() == 2u);
  CHECK(x31_writes.front() == gpr_gpa);            // base seed
  CHECK(x31_writes.back() == s.gpr[31]);           // architectural value
  CHECK(nonx31_gpr_writes == 0);

  // (c) with progbufsize=8 (7 loads/execution) the 30 loads take 5 Program-
  //     Buffer executions (7+7+7+7+2), not 30 abstract writes.
  int execs = 0;
  for (const auto& op : bus.ops)
    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
        && op.value == hybrid::kExecProgbufCmd)
      ++execs;
  CHECK(execs == 5);
}

