1	// StateDrain halts the hart via the Debug Module and populates a
2	// hybrid_state_v1 with the architectural register file. Reuses
3	// ResumeDriver's DM register constants and DmiBus interface.
4	
5	#pragma once
6	
7	#include "hybrid/abstract_command.hpp"
8	#include "hybrid/andes_caps.hpp"
9	#include "hybrid/dmi_poll.hpp"
10	#include "hybrid/resume_driver.hpp"
11	#include "hybrid/state_abi.h"
12	#include "hybrid/v_regfile_xfer.hpp"
13	
14	#include <algorithm>
15	#include <array>
16	#include <cstdint>
17	#include <span>
18	
19	namespace hybrid
20	{
21	
22	class StateDrain
23	{
24	public:
25	  using RD = ResumeDriver;
26	
27	  // scratch_gpa: the GUEST address of the V-register transport page (L26:
28	  // the mmap's top page, v_scratch_gpa(ram_base, ram_size)). Defaults to the
29	  // unset sentinel; only the V dump sweep consults it, and it throws there if
30	  // a V drain is reached with the GPA unset (no silent dump to a bogus
31	  // address). The simulator passes the real value from platform.main_memory.
32	  // caps: which Andes custom CSRs the TARGET core implements (from its
33	  // config.inc, supplied by the sim binary). Defaults to all() so existing
34	  // call sites are unchanged. Gates the Andes re-read below: reading an
35	  // unimplemented CSR can stall the DM, same as restoring one.
36	  explicit StateDrain(DmiBus& bus, uint64_t scratch_gpa = kVScratchGpaUnset,
37	                      AndesCaps caps = AndesCaps::all())
38	      : bus_{bus}, scratch_gpa_{scratch_gpa}, caps_{caps}
39	  {}
40	
41	  // Drain x1..x31 + PC. FP/CSR/V slots remain zero; merge them in via
42	  // drain_with_passthrough when the QEMU 1 snapshot is available.
43	  auto drain() -> hybrid_state_v1
44	  {
45	    halt("StateDrain halt");
46	
47	    hybrid_state_v1 state{};
48	    state.magic   = HYBRID_STATE_MAGIC;
49	    state.version = HYBRID_STATE_VERSION;
50	    state.flags   = HYBRID_FLAG_RV64;
51	    // L6: dcsr.prv holds the privilege the hart was in when the halt landed.
52	    state.priv = read_register_64(bus_, regno_csr(RD::kCsrDcsr),
53	                                  "StateDrain DCSR") & 0x3u;
54	
55	    for (uint16_t i = 1; i < 32; ++i)
56	      state.gpr[i] = read_register_64(bus_, regno_gpr(i), "StateDrain GPR");
57	
58	    state.pc = read_register_64(bus_, regno_csr(RD::kCsrDpc), "StateDrain DPC");
59	    return state;
60	  }
61	
62	  // Returns the input snapshot with x1..x31 and PC overwritten by a fresh
63	  // DM read. When HYBRID_FLAG_FP is set, also freshly reads f0..f31 + fcsr
64	  // (L20) so post-vsim FP modifications are captured (otherwise the stale
65	  // QEMU 1 snapshot leaks into the drained state). When HYBRID_FLAG_V is set, also
66	  // freshly reads the six V CSRs (vstart/vxsat/vxrm/vcsr/vtype/vl); vlenb
67	  // and vreg remain pass-through (read-only / too large for DM).
68	  // mcycle/minstret are always refreshed (F-T2.4): the vsim phase's
69	  // contribution would otherwise be discarded as the passthrough preserves
70	  // QEMU1's pre-handoff value.
71	  auto drain_with_passthrough(const hybrid_state_v1& input) -> hybrid_state_v1
72	  {
73	    auto state       = input;
74	    const auto fresh = drain();
75	    std::copy(std::begin(fresh.gpr) + 1, std::end(fresh.gpr),
76	              std::begin(state.gpr) + 1);
77	    state.pc   = fresh.pc;
78	    state.priv = fresh.priv;  // L6: privilege at the exit halt, not QEMU1's
79	
80	    if (input.flags & HYBRID_FLAG_FP) {
81	      for (uint16_t i = 0; i < 32; ++i)
82	        state.fpr[i] = read_register_64(bus_, regno_fpr(i), "StateDrain FPR");
83	      // L20: fcsr (frm + sticky fflags) accumulated by the vsim phase.
84	      state.fcsr = read_register_64(bus_, regno_csr(RD::kCsrFcsr));
85	    }
86	
87	    if (input.flags & HYBRID_FLAG_V) {
88	      state.vstart = read_register_64(bus_, regno_csr(RD::kCsrVstart));
89	      state.vxsat  = read_register_64(bus_, regno_csr(RD::kCsrVxsat));
90	      state.vxrm   = read_register_64(bus_, regno_csr(RD::kCsrVxrm));
91	      state.vcsr   = read_register_64(bus_, regno_csr(RD::kCsrVcsr));
92	      state.vtype  = read_register_64(bus_, regno_csr(RD::kCsrVtype));
93	      state.vl     = read_register_64(bus_, regno_csr(RD::kCsrVl));
94	    }
95	
96	    // L23: mscratch round-trips now (ResumeDriver restores it), so re-read it
97	    // from the hart -- otherwise an in-ROI write to the software scratch CSR is
98	    // dropped and the stale QEMU1 value passes through into the drained state.
99	    state.mscratch = read_register_64(bus_, regno_csr(RD::kCsrMscratch));
100	
101	    // L24: the writable M-mode trap/interrupt CSRs round-trip too (ResumeDriver
102	    // restores them), so re-read them -- an in-ROI write must reach the drained
103	    // state instead of the stale QEMU1 passthrough value.
104	    state.mepc   = read_register_64(bus_, regno_csr(RD::kCsrMepc));
105	    state.mcause = read_register_64(bus_, regno_csr(RD::kCsrMcause));
106	    state.mtval  = read_register_64(bus_, regno_csr(RD::kCsrMtval));
107	    state.mie    = read_register_64(bus_, regno_csr(RD::kCsrMie));
108	    state.mip    = read_register_64(bus_, regno_csr(RD::kCsrMip));
109	
110	    state.mcycle   = read_register_64(bus_, regno_csr(RD::kCsrMcycle));
111	    state.minstret = read_register_64(bus_, regno_csr(RD::kCsrMinstret));
112	
113	    // Andes V5 CSR block (v3): re-read the transported Andes CSRs from the hart
114	    // so an in-ROI write reaches the drained state instead of the stale QEMU1
115	    // passthrough (same round-trip as mscratch). caps_ gates each read to the
116	    // CSRs the core implements (reading an absent custom CSR can stall the DM,
117	    // same as restoring one); a skipped CSR keeps its passthrough value.
118	    // HYBRID_ANDES_CSR_LIST is the single source of truth shared with the
119	    // plugin drain, ResumeDriver, and state_diff.
120	    if (input.flags & HYBRID_FLAG_ANDES) {
121	#define X(field, addr, name) \
122	  if (caps_.supports_csr(addr)) \
123	    state.andes.field = read_register_64(bus_, regno_csr(addr));
124	      HYBRID_ANDES_CSR_LIST(X)
125	#undef X
126	      for (int i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
127	        if (caps_.supports_csr(HYBRID_PMA_CFG0_CSR + 2 * i))
128	          state.andes.pmacfg[i] =
129	            read_register_64(bus_, regno_csr(HYBRID_PMA_CFG0_CSR + 2 * i));
130	      for (int i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
131	        if (caps_.supports_csr(HYBRID_PMA_ADDR0_CSR + i))
132	          state.andes.pmaaddr[i] =
133	            read_register_64(bus_, regno_csr(HYBRID_PMA_ADDR0_CSR + i));
134	    }
135	
136	    // M-ext CSR block (v4): re-read the transported M-mode CSRs the core
137	    // implements, capability-gated by address like the Andes block. A skipped
138	    // CSR keeps its passthrough value. Same single-source X-macro.
139	    if (input.flags & HYBRID_FLAG_M_EXT) {
140	#define X(field, addr, name) \
141	  if (caps_.supports_csr(addr)) \
142	    state.m_ext.field = read_register_64(bus_, regno_csr(addr));
143	      HYBRID_M_EXT_CSR_LIST(X)
144	#undef X
145	    }
146	
147	    // V data regfile: dump v0..v31 to the shared scratch region via the
148	    // Program Buffer LAST -- after every architectural read above -- so the
149	    // sweep's clobbers (vtype/vl/vstart, x5/x6/x7) and its counter increments
150	    // cannot corrupt the values already captured. The simulator's
151	    // read_v_from_scratch then lifts the scratch bytes into state.vreg[].
152	    // Stride is HYBRID_VLEN_BYTES_MAX (the wire-format per-register span).
153	    if (input.flags & HYBRID_FLAG_V)
154	      dump_v_to_scratch(input.vlenb);
155	
156	    return state;
157	  }
158	
159	  // #1 (drain-minimal): refresh only mcycle/minstret from the hart and pass
160	  // every other field through from the QEMU1 snapshot. Used when --verify is
161	  // off: the driver then consumes only the vsim mcycle delta, so the full
162	  // register-file readback drain_with_passthrough performs (~190 DMI abstract
163	  // commands -- f0..f31, the V dump sweep, the Andes/M-ext blocks, ...) is pure
164	  // wasted wall-clock. The hart is left halted, identical to the full drain, so
165	  // the caller's file-write + exit path is unchanged.
166	  auto drain_counters_only(const hybrid_state_v1& input) -> hybrid_state_v1
167	  {
168	    halt("StateDrain halt (minimal)");
169	
170	    auto state     = input;
171	    state.mcycle   = read_register_64(bus_, regno_csr(RD::kCsrMcycle),
172	                                      "StateDrain mcycle");
173	    state.minstret = read_register_64(bus_, regno_csr(RD::kCsrMinstret),
174	                                      "StateDrain minstret");
175	    return state;
176	  }
177	
178	private:
179	  // Debug-Module halt-and-wait, shared by drain() and drain_counters_only():
180	  // dmactive must transition 0->1 in its own write before haltreq is honored
181	  // (RISC-V Debug Spec), then wait for allhalted. `ctx` labels the poll.
182	  void halt(const char* ctx)
183	  {
184	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
185	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
186	    poll_until_set(bus_, RD::kDmstatus, RD::kDmstatusAllhalted, ctx);
187	  }
188	
189	  // V data dump sweep: vse8.v v0..v31 from the regfile into the scratch page.
190	  // L26: guards on the configured scratch GPA so a V drain never stores to a
191	  // bogus address (mirror of ResumeDriver's reload-sweep guard).
192	  void dump_v_to_scratch(uint64_t vlenb)
193	  {
194	    if (scratch_gpa_ == kVScratchGpaUnset)
195	      throw std::runtime_error(
196	        "StateDrain: V state present but scratch GPA unset");
197	    pb_v_data_sweep(bus_, scratch_gpa_, vlenb, /*load=*/false);
198	  }
199	
200	  DmiBus& bus_;
201	  uint64_t scratch_gpa_ = kVScratchGpaUnset;  // L26: V transport page GPA
202	  AndesCaps caps_ = AndesCaps::all();         // target core's Andes-CSR support
203	};
204	
205	}  // namespace hybrid
