TEST_CASE("v_regfile_xfer: stage_csr with caps=none stages nothing")
{
  hybrid_state_v1 in{};
  in.flags = HYBRID_FLAG_RV64 | HYBRID_FLAG_ANDES | HYBRID_FLAG_M_EXT;
  in.andes.mxstatus = 0xAAAA;
  in.m_ext.menvcfg  = 0xBBBB;

  std::vector<uint8_t> ram(static_cast<size_t>(128) * 1024 * 1024);
  hybrid::stage_csr_to_scratch(in, ram, hybrid::AndesCaps::none());

  hybrid_state_v1 out{};
  out.flags = in.flags;
  out.andes.mxstatus = 0x1111;
  out.m_ext.menvcfg  = 0x2222;
  hybrid::read_csr_from_scratch(out, ram, hybrid::AndesCaps::none());

  CHECK(out.andes.mxstatus == 0x1111u);  // nothing lifted
  CHECK(out.m_ext.menvcfg  == 0x2222u);
}

