    // Andes V5 CSR block (v3): the boot-static memory-system / extension CSRs
    // the functional engine set up before the ROI -- PMA attributes, mxstatus,
    // ILM/DLM bases, perf throttling, stack-protection bounds, the CoDense/Zcmt
    // table bases -- plus the DSP overflow flag (ucode). Same rationale as
    // mcache_ctl: without them the cycle engine resumes with the wrong memory
    // system or faults on the first CoDense/DSP op in the window. caps_ gates
    // each write to the CSRs the TARGET core actually implements (from its
    // config.inc): restoring an absent custom CSR is NOT a clean no-op -- the
    // abstract write stalls the DM handshake (observed: ucode without DSP,
    // mecc_code without ECC). HYBRID_ANDES_CSR_LIST is the single source of
    // truth shared with the plugin drain, StateDrain, and state_diff.
    if (state.flags & HYBRID_FLAG_ANDES) {
#define X(field, addr, name) \
  if (caps_.supports_csr(addr)) write_csr_tolerant(addr, state.andes.field);
      HYBRID_ANDES_CSR_LIST(X)
#undef X
      // PMA: every pmaaddr before any pmacfg (a TOR/NAPOT cfg consumes the addr
      // already in place -- mirror the PMP ordering). On RV64 only even pmacfg
      // CSRs exist, so slot i maps to 0xBC0 + 2*i; pmaaddr i maps to 0xBD0 + i.
      for (uint16_t i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
        if (caps_.supports_csr(HYBRID_PMA_ADDR0_CSR + i))
          write_csr_tolerant(HYBRID_PMA_ADDR0_CSR + i, state.andes.pmaaddr[i]);
      for (uint16_t i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
        if (caps_.supports_csr(HYBRID_PMA_CFG0_CSR + 2 * i))
          write_csr_tolerant(HYBRID_PMA_CFG0_CSR + 2 * i, state.andes.pmacfg[i]);
    }

    // M-ext CSR block (v4): the writable M-mode CSRs across the whole SPA, each
    // capability-gated by address exactly like the Andes block above. caps_
    // skips any the target core lacks (most on an M-only core), so the absent
    // ones never stall the DM. Same single-source X-macro shared with the plugin
    // drain, StateDrain, and state_diff.
    if (state.flags & HYBRID_FLAG_M_EXT) {
#define X(field, addr, name) \
  if (caps_.supports_csr(addr)) write_csr_tolerant(addr, state.m_ext.field);
      HYBRID_M_EXT_CSR_LIST(X)
#undef X
    }

    // F-T2.4: restore mcycle/minstret so the vsim phase continues counting

