TEST_CASE("#v4 csr_sweep drain: Andes+M-ext drained via a PB csrr+sd sweep, "
          "no per-CSR abstract reads")
{
  RecordingBus bus;
  bus.dmstatus_value   = kDmstatusHaltedAndAcked;
  bus.abstractcs_value = 8u << 24;  // progbufsize=8

  hybrid_state_v1 input{};
  input.magic   = HYBRID_STATE_MAGIC;
  input.version = HYBRID_STATE_VERSION;
  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_ANDES | HYBRID_FLAG_M_EXT;
  input.priv    = 3;
  input.vlenb   = 0;  // csr_scratch_fits

  hybrid::StateDrain drain(bus, kScratch);  // caps all()
  drain.set_csr_sweep(true);
  (void) drain.drain_with_passthrough(input);

  std::vector<uint16_t> addrs;
  hybrid::for_each_sweep_csr(input, hybrid::AndesCaps::all(),
    [&](std::size_t, uint16_t addr, const uint64_t&) { addrs.push_back(addr); });
  REQUIRE(!addrs.empty());

  auto progbuf_has = [&](uint32_t insn) {
    for (const auto& op : bus.ops)
      if (op.kind == DmiOp::Kind::Write && op.reg >= hybrid::kProgbuf0
          && op.reg <= hybrid::kProgbuf0 + hybrid::kProgbufMaxInsns
          && op.value == insn) return true;
    return false;
  };
  // (a) each supported CSR: csrr into x5 + sd to its scratch slot.
  for (std::size_t k = 0; k < addrs.size(); ++k) {
    CHECK(progbuf_has(hybrid::encode_csrrs(5, addrs[k], 0)));
    CHECK(progbuf_has(hybrid::encode_sd(5, 6, int32_t(k * 8))));
  }
  // (b) no swept CSR is drained via an abstract read-COMMAND (they rode the sweep).
  int abstract_reads = 0;
  for (const auto& op : bus.ops) {
    if (op.kind != DmiOp::Kind::Write || op.reg != RD::kCommand) continue;
    if (((op.value >> 16) & 1u) != 0u) continue;  // reads only
    const uint16_t regno = op.value & 0xFFFFu;
    for (uint16_t a : addrs) if (regno == hybrid::regno_csr(a)) ++abstract_reads;
  }
  CHECK(abstract_reads == 0);
}
