#include "process.hpp"

#include <cerrno>
#include <ctime>

#include <fcntl.h>
#include <poll.h>
#include <signal.h>
#include <sys/wait.h>
#include <unistd.h>

namespace andes_sim {
namespace {

long now_ms() {
  struct timespec ts;
  clock_gettime(CLOCK_MONOTONIC, &ts);
  return ts.tv_sec * 1000L + ts.tv_nsec / 1000000L;
}

// In the just-forked child: replace the image with argv (argv[0] resolved via
// PATH), or _exit(127) if exec fails. Never returns.
[[noreturn]] void exec_or_die(const std::vector<std::string>& argv) {
  std::vector<char*> cargv;
  cargv.reserve(argv.size() + 1);
  for (const std::string& a : argv) cargv.push_back(const_cast<char*>(a.c_str()));
  cargv.push_back(nullptr);
  execvp(cargv[0], cargv.data());
  _exit(127);  // exec failed
}

// Reap `pid` and map its wait status to an exit code: the child's exit code,
// 128+signal if it was signalled, or -1 otherwise.
int wait_for_exit_code(pid_t pid) {
  int status = 0;
  waitpid(pid, &status, 0);
  if (WIFEXITED(status)) return WEXITSTATUS(status);
  if (WIFSIGNALED(status)) return 128 + WTERMSIG(status);
  return -1;
}

// fork + (optional chdir) + (optional stdin from /dev/null) + exec.
// When `wait` is true (the default) waits for the child and returns its exit
// code, 128+signal if signalled, or -1 on failure. When `wait` is false
// returns the child pid immediately without waiting (caller owns the child).
// Backs run_inherit (build: stdin closed, chdir), exec_passthrough (run
// fast/cycle: stdin inherited, no chdir), and fork_background (no wait).
int spawn_inherit(const std::vector<std::string>& argv, const std::string& cwd,
                  bool stdin_from_devnull, bool wait = true) {
  if (argv.empty()) return -1;

  pid_t pid = fork();
  if (pid < 0) return -1;

  if (pid == 0) {  // child
    if (!cwd.empty() && chdir(cwd.c_str()) != 0) _exit(127);
    if (stdin_from_devnull) {
      int devnull = open("/dev/null", O_RDONLY);
      if (devnull >= 0) {
        dup2(devnull, STDIN_FILENO);
        if (devnull > 2) close(devnull);
      }
    }
    exec_or_die(argv);
  }

  if (!wait) return static_cast<int>(pid);
  return wait_for_exit_code(pid);
}

}  // namespace

RunResult run_process(const std::vector<std::string>& argv, int timeout_ms) {
  RunResult r;
  if (argv.empty()) {
    r.spawn_failed = true;
    return r;
  }

  int fds[2];
  if (pipe(fds) != 0) {
    r.spawn_failed = true;
    return r;
  }

  pid_t pid = fork();
  if (pid < 0) {
    close(fds[0]);
    close(fds[1]);
    r.spawn_failed = true;
    return r;
  }

  if (pid == 0) {  // child
    close(fds[0]);
    dup2(fds[1], STDOUT_FILENO);
    int devnull = open("/dev/null", O_RDWR);
    if (devnull >= 0) {
      dup2(devnull, STDIN_FILENO);
      dup2(devnull, STDERR_FILENO);
      if (devnull > 2) close(devnull);
    }
    close(fds[1]);
    exec_or_die(argv);
  }

  // parent
  close(fds[1]);
  int rfd = fds[0];
  const long deadline = now_ms() + timeout_ms;
  char buf[4096];

  while (true) {
    long remaining = deadline - now_ms();
    if (remaining < 0) remaining = 0;
    struct pollfd pfd{rfd, POLLIN, 0};
    int pr = poll(&pfd, 1, static_cast<int>(remaining));
    if (pr < 0) {
      if (errno == EINTR) continue;
      break;
    }
    if (pr == 0) {  // timed out with no data ready
      kill(pid, SIGKILL);
      r.timed_out = true;
      break;
    }
    if (pfd.revents & (POLLIN | POLLHUP | POLLERR)) {
      ssize_t n = read(rfd, buf, sizeof(buf));
      if (n > 0) {
        r.out.append(buf, static_cast<size_t>(n));
      } else if (n == 0) {
        break;  // EOF: child closed stdout
      } else {
        if (errno == EINTR) continue;
        break;
      }
    }
    if (now_ms() >= deadline) {  // chatty child kept us past the deadline
      kill(pid, SIGKILL);
      r.timed_out = true;
      break;
    }
  }

  close(rfd);
  int status = 0;
  waitpid(pid, &status, 0);
  // rc stays -1 (the default) when timed out or abnormally terminated.
  if (!r.timed_out && WIFEXITED(status)) r.rc = WEXITSTATUS(status);
  return r;
}

int run_inherit(const std::vector<std::string>& argv, const std::string& cwd) {
  return spawn_inherit(argv, cwd, /*stdin_from_devnull=*/true);
}

int exec_passthrough(const std::vector<std::string>& argv) {
  return spawn_inherit(argv, /*cwd=*/"", /*stdin_from_devnull=*/false);
}

int fork_background(const std::vector<std::string>& argv) {
  return spawn_inherit(argv, /*cwd=*/"", /*stdin_from_devnull=*/false, /*wait=*/false);
}

namespace {

// Drain everything readable on `fd` into `buf`, delivering each completed
// '\n'-terminated line (newline stripped) to on_line. Returns false at EOF /
// error so the caller stops polling that stream.
bool pump_stream(int fd, int stream, std::string& buf,
                 const std::function<void(int, std::string_view)>& on_line) {
  char rb[4096];
  const ssize_t n = read(fd, rb, sizeof rb);
  if (n == 0) return false;          // EOF: child closed this stream
  if (n < 0) return errno == EINTR;  // transient -> keep; real error -> stop
  buf.append(rb, static_cast<size_t>(n));
  size_t nl;
  while ((nl = buf.find('\n')) != std::string::npos) {
    on_line(stream, std::string_view(buf.data(), nl));
    buf.erase(0, nl + 1);
  }
  return true;
}

}  // namespace

int run_line_filtered(
    const std::vector<std::string>& argv,
    const std::function<void(int, std::string_view)>& on_line) {
  if (argv.empty()) return -1;

  int out_fds[2], err_fds[2];
  if (pipe(out_fds) != 0) return -1;
  if (pipe(err_fds) != 0) {
    close(out_fds[0]);
    close(out_fds[1]);
    return -1;
  }

  pid_t pid = fork();
  if (pid < 0) {
    close(out_fds[0]);
    close(out_fds[1]);
    close(err_fds[0]);
    close(err_fds[1]);
    return -1;
  }

  if (pid == 0) {  // child: stdout/stderr to the pipes, stdin inherited
    close(out_fds[0]);
    close(err_fds[0]);
    dup2(out_fds[1], STDOUT_FILENO);
    dup2(err_fds[1], STDERR_FILENO);
    if (out_fds[1] > 2) close(out_fds[1]);
    if (err_fds[1] > 2) close(err_fds[1]);
    exec_or_die(argv);
  }

  // parent: poll both pipes, line-buffer each, until both hit EOF. No timeout --
  // matches exec_passthrough (a cycle run can be arbitrarily long). The stream id
  // is index+1 (0 -> stdout=1, 1 -> stderr=2); a closed stream's fd is set to -1,
  // which poll() ignores (revents 0).
  close(out_fds[1]);
  close(err_fds[1]);
  const int fd[2] = {out_fds[0], err_fds[0]};
  std::string buf[2];
  bool open_[2] = {true, true};

  struct pollfd pfd[2] = {{fd[0], POLLIN, 0}, {fd[1], POLLIN, 0}};
  while (open_[0] || open_[1]) {
    for (int i = 0; i < 2; ++i) pfd[i].fd = open_[i] ? fd[i] : -1;
    if (poll(pfd, 2, -1) < 0) {
      if (errno == EINTR) continue;
      break;
    }
    for (int i = 0; i < 2; ++i)
      if (open_[i] && (pfd[i].revents & (POLLIN | POLLHUP | POLLERR)))
        if (!pump_stream(fd[i], i + 1, buf[i], on_line)) open_[i] = false;
  }
  // Flush any final line that arrived without a trailing newline.
  for (int i = 0; i < 2; ++i)
    if (!buf[i].empty()) on_line(i + 1, buf[i]);

  close(fd[0]);
  close(fd[1]);
  return wait_for_exit_code(pid);
}

}  // namespace andes_sim

// The phase-plan executor (F6) -- the C++ analog of runner.run_session, minus
// the dropped QEMU2 handback. run_plan spawns each leg of a Plan in order,
// threads the drained hybrid_state_v1 file forward (leg N's --handoff-out is
// leg N+1's --resume-from-qemu), and reports each leg's mcycle/minstret.
//
// plan_argvs is the pure core (no spawn, no mmap): it resolves each Step's
// engine + role against the registry and fills the invoke template with the
// threaded state paths, so the argv construction is unit-testable in isolation.
#ifndef ANDESIM_RUN_PLAN_HPP
#define ANDESIM_RUN_PLAN_HPP

#include <string>
#include <vector>

#include "engine_descriptor.hpp"
#include "plan.hpp"
#include "process.hpp"

namespace andes_sim {

// The framework-owned values shared by every leg of a run: the resolved
// shared-mmap path/size/base and the QEMU plugin path. Per-leg values
// (bin/state_in/state_out) are derived by plan_argvs from this + the threading.
struct RuntimeCtx {
  std::string mmap_path;
  long long mem_size = 0;
  std::string mmap_base = "0x0";
  std::string plugin_path;
  // QEMU `-readconfig` file matching the accurate engine's ISA, distilled from
  // its config.inc (the engine's `--print-qemu-config`). Empty => the fast leg
  // keeps its descriptor's default `-cpu` (engines without the flag; FA2).
  std::string qemu_cfg;
};

// hw-config sync: the QEMU fast leg models the hardware the accurate-leg
// engine measures, so its -cpu vlen follows that engine's descriptor. 512 is
// the fallback for engines that report none. One definition, used by both the
// plan executor ({vlen} fill) and the hybrid banner.
inline long synced_vlen(long engine_vlen) {
  return engine_vlen > 0 ? engine_vlen : 512;
}

// A trigger's per-leg argv contribution, dispatched by the leg's role. The
// QEMU plugin takes its trigger as a comma-suffix folded INTO the one `-plugin`
// token (so it rides the `{trigger}` placeholder); vsim takes separate tokens
// appended to its argv. marker contributes nothing (plugin/vsim detect the markers
// themselves).
struct LegTriggerArgs {
  std::string plugin_suffix;        // qemu fast-leg: appended to {trigger}
  std::vector<std::string> extra;   // vsim accurate-leg: appended tokens
};

// Map `t` onto `role`'s argv contribution. marker -> empty. pc -> qemu
// `,enter_pc=<enter_pc>` / vsim `--hybrid-exit-pc <exit_pc>`. Roles other
// than fast-leg/accurate-leg get nothing. A missing required param or an
// unknown trigger kind sets `err` (and returns an empty contribution).
//
// NOTE (altitude debt): these flag spellings are framework-side per-engine
// knowledge -- the one place F9 hardcodes a fast/accurate engine's CLI, unlike
// the base argv which comes from each engine's `--describe` invoke template.
// This is a deliberate scope cut: the principled form (per-(trigger,role) argv
// templates carried in `--describe`, filled by build_argv like `invoke`) would
// extend the F2 engine contract and is left for a later feature.
LegTriggerArgs leg_trigger_args(const Trigger& t, const std::string& role,
                                std::string& err);

// Turn an accurate engine's `<bin> --print-qemu-config` probe into a QEMU
// `-readconfig` file under `workdir`. On a clean probe (exit 0, non-empty
// stdout) writes `workdir/qemu.cfg` and returns its path; on any failure
// (engine without the flag -> the parser throws -> non-zero exit; timeout;
// spawn failure; empty output; unwritable dir) returns "" -- the tolerant
// fallback that leaves the fast leg on its descriptor's default -cpu.
std::string stage_qemu_cfg(const std::string& workdir, const RunResult& probe);

// Build every step's concrete argv, threading state files under `workdir`:
//   state_in[0]  = ""                       (cold start; no resume)
//   state_in[i]  = state_out[i-1]           (prior leg's drain)
//   state_out[i] = workdir/"state-<i>.bin"  (this leg's drain)
// Each step's engine is looked up in `engines` by id and its `role` template is
// filled via build_argv. Pure (no spawn). Returns one argv per step; on any
// error (unknown engine/role, unresolved placeholder) returns {} and sets `err`.
std::vector<std::vector<std::string>> plan_argvs(
    const Plan& plan, const std::vector<EngineDescriptor>& engines,
    const std::string& workdir, const RuntimeCtx& ctx, std::string& err);

// The exit code a leg returns after draining its state and handing off (the
// driver-side mirror of vsim's kExitHandoffToQemu). Every plan step is a drain
// step, so this is the expected per-leg exit.
constexpr int kDrainRc = 200;

struct PlanOptions {
  int timeout_ms = 90000;     // per-leg spawn timeout
  int expect_rc = kDrainRc;   // drain success code
  std::string plugin_path;    // "" => $VSIM_PLUGIN else repo default
  bool dry_run = false;       // build argvs (incl. qemu_cfg) but spawn nothing
};

// Compose the "plan step N exited wrong" diagnostic. A drain step (expect_rc is
// the handoff/drain code) that exits 0 ran the ELF to completion without ever
// reaching its ROI boundary -- the marker/pc trigger never fired; say so and
// name the trigger kind so the fix (right ELF / right --trigger) is obvious.
// Any other mismatch gets the plain "expected X, got Y" line.
std::string plan_step_rc_error(size_t step, const Step& s, int expect_rc,
                               int got_rc);

// Execute `plan`: resolve the plugin, acquire the shared mmap (allocate one
// under /dev/shm when plan.mmap_path is empty, and own it), spawn each leg with
// a timeout, require exit == expect_rc, and read back each leg's mcycle/minstret
// from its drained state file. Returns the per-leg results; on the first failure
// `error` describes it and `phases` holds whatever completed before it.
PlanResult run_plan(const Plan& plan,
                    const std::vector<EngineDescriptor>& engines,
                    const PlanOptions& opts = {});

}  // namespace andes_sim

#endif  // ANDESIM_RUN_PLAN_HPP

