40	  static constexpr bool is_axi = (CPU::SYSTEM_BUS_TYPE == BusTypes::AXI);
41	  static constexpr auto bus_width = PLATFORM::data_width;
42	
43	  // Helper: create an AXI→TLM bridge, bind clock, connect initiator BFM
44	  auto make_axi_to_tlm(const char* name, auto& bfm_socket)
45	    -> std::unique_ptr<axi_to_tlm_bridge<bus_width>>
46	  {
47	    auto bridge = std::make_unique<axi_to_tlm_bridge<bus_width>>(name);
48	    bridge->pe.clk_i.bind(platform.clk);
49	    bfm_socket.bind(bridge->axi_tsck);
