53	  // Helper: create a TLM→AXI bridge, bind clock, connect target BFM
54	  auto make_tlm_to_axi(const char* name, auto& bfm_socket)
55	    -> std::unique_ptr<tlm_to_axi_bridge<bus_width>>
56	  {
57	    auto bridge = std::make_unique<tlm_to_axi_bridge<bus_width>>(name);
58	    bridge->pe.clk_i.bind(platform.clk);
59	    bridge->axi_isck.bind(bfm_socket);
