65	  PLATFORM platform;
66	
67	  // AXI bridges (only used when is_axi == true, null otherwise)
68	  std::unique_ptr<axi_to_tlm_bridge<bus_width>> mem_bridge;
69	  std::unique_ptr<axi_to_tlm_bridge<bus_width>> mmio_bridge;
70	  std::unique_ptr<tlm_to_axi_bridge<bus_width>> hvm_bridge;
