94	  // handoff_, so it must be declared first.
95	  std::unique_ptr<hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width,
96	                                        PLATFORM::dmi_data_width>>
97	    hybrid_dmi_bus_;
98	  std::optional<hybrid::HandoffController<hybrid::CsrTrigger>>
99	    hybrid_handoff_;
100	  std::string hybrid_state_path_;
101	  std::optional<hybrid_state_v1> hybrid_input_state_;
102	
103	  using xlen_t = std::conditional_t<CPU::NDS_XLEN <= 32, uint32_t, uint64_t>;
104	
105	public:
106	  ContextManager<CPU> context_config;
107	
108	  Simulator(const sc_core::sc_module_name& name,
109	            std::span<uint8_t> ram_buffer = {},
110	            MemoryRegion ram_region = {RAM_BASE, RAM_END},
111	            MemoryRegion ram_alias_region = {RAM_ALIAS_BASE, RAM_ALIAS_END})
112	      : sc_core::sc_module{name},
113	        platform("platform", ram_buffer, ram_region, ram_alias_region),
114	        dtm(platform.dtm)
115	  {
116	    cpu.bind(platform.clk, platform.resetn, platform.reset_vector,
117	             platform.dmi_signals, platform.wfi_signal, platform.int_trigger);
118	
119	    // --- CPU memory BFM → interconnect ---
120	    if constexpr (is_axi) {
121	      mem_bridge = make_axi_to_tlm("mem_bridge", cpu.mem_bfm.isckt);
122	      platform.interconnect.bind_initiator(mem_bridge->tlm_isck);
123	    } else {
124	      platform.interconnect.bind_initiator(cpu.mem_bfm.isckt);
125	    }
126	
127	    // --- CPU MMIO BFM → interconnect ---
128	    if constexpr (requires { cpu.mmio_bfm; }) {
129	      if constexpr (is_axi) {
130	        mmio_bridge = make_axi_to_tlm("mmio_bridge", cpu.mmio_bfm.isckt);
131	        platform.interconnect.bind_initiator(mmio_bridge->tlm_isck);
132	      } else {
133	        platform.interconnect.bind_initiator(cpu.mmio_bfm.isckt);
134	      }
135	    }
136	
137	    // --- CPU HVM subordinate port ---
138	    if constexpr (requires { cpu.hvm_bfm; }) {
139	      if constexpr (is_axi) {
140	        hvm_bridge = make_tlm_to_axi("hvm_bridge", cpu.hvm_bfm.tsckt);
141	        platform.interconnect.bind_target(
142	          hvm_bridge->tlm_tsck,
143	          {CPU::NDS_HVM_BASE,
144	           CPU::NDS_HVM_BASE + CPU::NDS_HVM_SIZE_KB * 0x1000 - 1});
145	      } else {
146	        platform.interconnect.bind_target(
147	          cpu.hvm_bfm.tsckt,
148	          {CPU::NDS_HVM_BASE,
149	           CPU::NDS_HVM_BASE + CPU::NDS_HVM_SIZE_KB * 0x1000 - 1});
150	      }
151	      platform.custom_master.hvm_base = CPU::NDS_HVM_BASE;
152	    }
153	
154	    // --- CPU slave port ---
155	    if constexpr (requires { cpu.slv_bfm; }) {
156	      if constexpr (is_axi) {
157	        slv_bridge = make_tlm_to_axi("slv_bridge", cpu.slv_bfm.tsckt);
158	        platform.interconnect.bind_target(slv_bridge->tlm_tsck,
159	                                          {HART0_ILM_BASE, HART0_DLM_END});
160	      } else {
