168	    // --- CPU sys bus (slave port, 64-bit) → interconnect ---
169	    if constexpr (requires { cpu.sys_bfm; }) {
170	      sys_adapter =
171	        std::make_unique<socket_width_adapter<bus_width, sys_bus_width>>(
172	          "sys_adapter");
173	      sys_bridge =
174	        std::make_unique<tlm_to_axi_bridge<sys_bus_width>>("sys_bridge");
175	      sys_bridge->pe.clk_i.bind(platform.clk);
176	      sys_bridge->axi_isck.bind(cpu.sys_bfm.tsckt);
177	      sys_adapter->isck.bind(sys_bridge->tlm_tsck);
178	      platform.interconnect.bind_target(sys_adapter->tsck,
179	                                        {MLIF_BASE, SLIF_END});
180	    }
181	
182	#if _NDS_IOCP_NUM > 0
183	    iocp_master.protocol_engine.clk_i.bind(platform.clk);
184	    iocp_master.socket.bind(cpu.iocp_bfm.tsckt);
185	#endif // _NDS_IOCP_NUM
186	  }
