188	  ~Simulator() { trace_.close(); }
189	
190	  void init_debug_port(const uint16_t port = 9104)
191	  {
192	    dtm_debug = true;
193	    dtm.init_port(port);
194	    spdlog::info("waiting for debugger connection");
195	  }
196	
197	  // Caller invariant: the CPU must already be out of reset.
198	  void apply_resume_from_qemu(const std::string& path)
199	  {
200	    hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width, PLATFORM::dmi_data_width>
201	      bus{platform.dmi, platform.clk.period()};
202	    hybrid_input_state_ = hybrid::load_state(path);
203	    // Stage V-register bytes into the fixed scratch region of RAM BEFORE
204	    // resume: ResumeDriver's Program-Buffer reload sweep issues vle8.v from
205	    // this region to repopulate v0..v31, so the bytes must be in place first.
206	    // Best-effort: mismatched RAM layouts throw, which is louder than silently
207	    // dropping V state.
208	    if ((hybrid_input_state_->flags & HYBRID_FLAG_V) != 0u) {
209	      hybrid::stage_v_to_scratch(*hybrid_input_state_,
210	                                 platform.main_memory.data);
211	    }
212	    // GPR block-load: stage x1..x31 into the scratch page so the resume
213	    // ld-sweep repopulates them in ~6 DM round-trips instead of 31 abstract
214	    // writes. Host memcpy is free. Gate on gpr_scratch_fits -- the same
215	    // condition ResumeDriver uses -- so when the V data fills the page we skip
216	    // staging (the abstract-write fallback runs) and never clobber v30/v31.
217	    if (hybrid::gpr_scratch_fits(hybrid_input_state_->vlenb))
218	      hybrid::stage_gpr_to_scratch(*hybrid_input_state_,
219	                                   platform.main_memory.data);
220	    // FPR block-load: stage f0..f31 just below the GPR block so the resume
221	    // fld-sweep repopulates them in ~6 DM round-trips instead of 32 abstract
222	    // writes. Gate on the FP flag and fpr_scratch_fits (tighter than the GPR
223	    // gate -- the FPR block sits lower in the page), so a full V page skips
224	    // staging and the abstract-write fallback runs.
225	    if ((hybrid_input_state_->flags & HYBRID_FLAG_FP) != 0u
226	        && hybrid::fpr_scratch_fits(hybrid_input_state_->vlenb))
227	      hybrid::stage_fpr_to_scratch(*hybrid_input_state_,
228	                                   platform.main_memory.data);
229	    // NOTE: the RESTORE csr_sweep stays OFF. A csrrw to a caps-supported but
230	    // read-only / WARL-illegal CSR raises cmderr in the Program Buffer, and a
231	    // batched sweep cannot tolerate a mid-batch fault the way the abstract path's
232	    // per-CSR clear_cmderr does. Restoring those CSRs is a no-op anyway (can't
233	    // write a read-only CSR), so restore keeps the abstract-tolerant path until a
234	    // per-CSR writability model can gate the sweep. The DRAIN sweep IS on (csrr
235	    // reads never fault for a readable CSR) -- see set_block_store_drain.
236	    hybrid::ResumeDriver driver(bus, v_scratch_gpa(),
237	                                hybrid::andes_caps_from_config());
238	    driver.set_gpr_block_load(true);
239	    driver.set_fpr_block_load(true);
240	    driver.resume(*hybrid_input_state_);
241	  }
242	
243	  // Enables the vsim->QEMU handoff drain. After this is set, run() watches
244	  // committed PCs and on retire of a `csrw 0x7C0, *` exit-trigger drains
245	  // architectural state to `state_out_path` and returns kExitHandoffToQemu.
246	  //
247	  // When `exit_pc` is set, the trigger is populated by `add_pc_hit` (PC
248	  // mode) and the ELF scan is skipped: the binary need not contain a magic
249	  // csrwi marker. CSR mode and PC mode are mutually exclusive on a single
250	  // run -- callers pass exactly one form.
251	  void enable_hybrid_handoff(const std::string& elf_path,
252	                             const std::string& state_out_path,
253	                             std::optional<uint64_t> exit_pc = std::nullopt,
254	                             bool drain_minimal = false)
255	  {
256	    hybrid::CsrTrigger trigger;
257	    if (exit_pc) {
258	      trigger.add_pc_hit(*exit_pc, HYBRID_HANDOFF_EXIT);
259	      spdlog::info("hybrid: PC-trigger mode, exit_pc=0x{:x}", *exit_pc);
260	    } else {
261	      auto elf = LIEF::ELF::Parser::parse(elf_path);
262	      if (!elf)
263	        throw std::runtime_error(
264	          "enable_hybrid_handoff: failed to parse " + elf_path);
265	      for (const auto& seg: elf->segments()) {
266	        if (seg.type() != LIEF::ELF::SEGMENT_TYPES::PT_LOAD) continue;
267	        if ((static_cast<unsigned>(seg.flags()) & 1u) == 0u) continue;  // PF_X
268	        const auto content = seg.content();
269	        const std::span<const uint8_t> bytes{content.data(), content.size()};
270	        trigger.scan_buffer(bytes, seg.virtual_address());
271	      }
272	    }
273	
274	    hybrid_dmi_bus_ = std::make_unique<
275	      hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width,
276	                            PLATFORM::dmi_data_width>>(platform.dmi,
277	                                                       platform.clk.period());
278	    hybrid_handoff_.emplace(std::move(trigger), *hybrid_dmi_bus_,
279	                            v_scratch_gpa(), hybrid::andes_caps_from_config());
280	    if (hybrid_input_state_)
281	      hybrid_handoff_->set_passthrough_input(*hybrid_input_state_);
282	    hybrid_handoff_->set_minimal_drain(drain_minimal);
283	    hybrid_handoff_->set_block_store_drain(true);
284	    hybrid_state_path_ = state_out_path;
285	  }
286	
287	private:
288	  // L26: the GUEST address of the V-register transport page -- the top page of
289	  // the mapped RAM span. The driver maps one page above --mem-size (scheme D),
290	  // so this sits just past the program's declared RAM and never collides with
291	  // its data/stack. Single source of truth handed to ResumeDriver/StateDrain.
292	  auto v_scratch_gpa() const -> uint64_t
293	  {
294	    return hybrid::v_scratch_gpa(platform.main_memory.region.base_address,
295	                                 platform.main_memory.data.size());
296	  }
297	
298	public:
299	
300	  void restore_context(const std::string& dir)
301	  {
302	    context_config.dir = dir;
303	    context_config.restore(platform, cpu);
304	  }
305	
306	  void save_context(const std::string& dir)
307	  {
308	    context_config.dir = dir;
309	    context_config.save(platform, cpu);
310	  }
311	
312	  // skip_memory_load: parse the ELF and set the reset vector, but leave
313	  // platform.main_memory untouched. Used in tier-2 hybrid resume where
314	  // QEMU 1's -kernel already populated the shared mmap; re-loading would
315	  // zero-fill the .bss tail of each PT_LOAD and destroy phase-1 writes
316	  // to static buffers. The reset vector is still set so the hart has a
317	  // valid fetch target during the post-reset cycles that precede the DMI
318	  // halt+DPC-write resume sequence.
319	  void load_elf(const std::string& path, bool skip_memory_load = false)
320	  {
321	    const auto elf = LIEF::ELF::Parser::parse(path);
322	    if (!elf) {
323	      spdlog::critical("Check if it's a valid ELF file path : {}", path);
324	      exit(1);
325	    }
326	
327	    if (!skip_memory_load)
328	      read_elf_into_memory(
329	        *elf,
330	        static_cast<xlen_t>(platform.main_memory.region.base_address),
331	        platform.main_memory.data);
332	    for (auto& rv: platform.reset_vector)
333	      rv.write(elf->entrypoint());
334	  }
335	
336	  void set_reset_vector(size_t hart, uint64_t addr)
337	  {
338	    if (hart >= platform.reset_vector.size()) {
339	      spdlog::critical("hart {} out of range (max {})", hart,
340	                       platform.reset_vector.size() - 1);
341	      std::exit(EXIT_FAILURE);
342	    }
343	    platform.reset_vector[hart].write(addr);
344	  }
345	
346	  void load_image(const std::string& path, MEM_TYPE type)
347	  {
348	    switch (type) {
349	    case MEM_TYPE::ILM:
350	      if constexpr (requires { cpu.set_ilm({}); }) {
351	        read_binary_file(path, [this](const auto& data) { cpu.set_ilm(data); });
352	      } else {
353	        throw std::runtime_error(
354	          "CPU does not support ILM - cannot load ILM ROM image");
355	      }
356	      break;
357	
358	    case MEM_TYPE::DLM:
359	      if constexpr (requires { cpu.set_dlm({}); }) {
360	        read_binary_file(path, [this](const auto& data) { cpu.set_dlm(data); });
361	      } else {
362	        throw std::runtime_error(
363	          "CPU does not support DLM - cannot load DLM ROM image");
364	      }
365	      break;
366	
367	    case MEM_TYPE::RAM:
368	      read_binary_file(path, [this](const auto& data) {
369	        if (data.size() > platform.main_memory.data.size())
370	          throw std::runtime_error("RAM image size exceeds main memory size");
371	        std::copy(data.begin(), data.end(), platform.main_memory.data.begin());
372	      });
373	      break;
374	
375	    default:
376	      throw std::runtime_error("Unknown memory type");
377	    }
378	  }
379	
380	  void reset()
381	  {
382	    static constexpr int core_num = CPU::NDS_NHART;
383	    static constexpr int reset_val = (1 << core_num) - 1;
384	
385	    platform.resetn.write(0);
386	    auto saved = context_config;
387	    context_config = {};
388	    this->run(1);
389	    context_config = saved;
390	
391	    for (size_t i = 0; i < platform.reset_vector.size(); ++i)
392	      spdlog::info("hart {} reset vector: {:#x}", i,
393	                   (uint64_t) platform.reset_vector[i].read());
394	
395	    platform.resetn.write(reset_val);
396	
397	    if (context_config.continue_from)
398	      restore_context(context_config.dir);
399	  }
400	
401	  int run(const uint64_t max_cycles = std::numeric_limits<uint64_t>::max())
402	  {
403	    auto sa = memzeroed<struct sigaction>();
404	    sa.sa_handler = sigint_handler;
405	    sigemptyset(&sa.sa_mask);
406	
407	    auto oact = memzeroed<struct sigaction>();
408	    if (sigaction(SIGINT, &sa, &oact) == -1)
409	      perror("sigaction");
410	
411	    const auto restore_sigint = std::experimental::scope_exit{[&] {
412	      if (sigaction(SIGINT, &oact, nullptr) == -1)
413	        perror("sigaction");
414	    }};
415	
416	    // wait for debugger connections
417	    while (dtm_debug && !dtm.is_connected()) {
418	      dtm.try_accept_socket();
419	      if (ctrlc != 0) {
420	        return 130;
421	      }
422	      sleep(1);
423	    }
424	
425	    [[maybe_unused]]
426	    bool ctx_resuming = context_config.continue_from;
427	    [[maybe_unused]]
428	    bool ctx_triggered = false;
429	
430	    for (auto n = uint64_t{0}; n < max_cycles; ++n) {
431	
432	      if (ctx_resuming) [[unlikely]] {
433	        // Pull up PLIC interrupt signal at the first cycle of the resume
434	        platform.int_trigger.write(1);
435	        ctx_resuming = false;
436	        ctx_triggered = true;
437	      }
438	
439	      sc_core::sc_start(platform.clk.period());
440	
441	      trace_.on_cycle(cpu);
442	
443	      if (hybrid_handoff_) [[unlikely]] {
444	        if (auto code = check_hybrid_handoff(); code) return *code;
445	      }
446	
447	      if (context_config.save_on_wfi && platform.wfi_signal.read() == true)
448	        [[unlikely]]
449	      {
450	        context_config.save(platform, cpu);
451	        spdlog::info("User save context");
452	        return 0;
453	      }
454	
455	      if (ctrlc != 0) {
456	        ctrlc = 0;
457	        spdlog::info("Ctrl+C PC: {:x}", get_current_pc());
458	        trace_.log_committed_pcs(cpu);
459	        return 130;
460	      }
461	
462	      if (ctx_triggered) [[unlikely]] {
463	        // Pull down the interrupt signal after 1 cycle
464	        platform.int_trigger.write(0);
465	        ctx_triggered = false;
466	      }
467	
468	      if (platform.sim_control.exits >= 0) {
469	        spdlog::info("sim_control: got exit {}, stopping",
470	                     platform.sim_control.exits);
471	        spdlog::info("Exit PC: {:x}", get_current_pc());
472	        trace_.log_committed_pcs(cpu);
473	        return platform.sim_control.exits;
474	      }
475	
476	      if (this->cpu.contextp()->gotFinish())
477	        return 0;
478	
479	      spdlog::trace("PC: {:x}", get_current_pc());
480	    }
481	    return 0;
482	  }
483	
484	  uint64_t get_current_pc()
485	  {
486	    if constexpr (requires { cpu.get_current_pc(); }) {
487	      return cpu.get_current_pc();
488	    }
489	    return std::numeric_limits<uint64_t>::max();
490	  }
491	
492	  auto check_hybrid_handoff() -> std::optional<int>
493	  {
494	    if constexpr (!requires { cpu.get_committed_pc(); }) {
495	      return std::nullopt;
496	    } else {
497	      const auto committed = cpu.get_committed_pc();
498	      if (committed.empty()) return std::nullopt;
499	      for (const auto pc: committed[0]) {
500	        auto state = hybrid_handoff_->on_retire(pc);
501	        if (state) {
502	          // V-register merge: the fixture's vsim-phase epilogue is expected
503	          // to have run vse8.v v0..v31 to scratch RAM before the exit
504	          // trigger fired. Read those bytes back into state.vreg[] so the
505	          // drained handoff state carries vsim's actual V values, not
506	          // QEMU 1's stale snapshot.
507	          if ((state->flags & HYBRID_FLAG_V) != 0u) {
508	            hybrid::read_v_from_scratch(
509	              *state,
510	              std::span<const uint8_t>{platform.main_memory.data.data(),
511	                                       platform.main_memory.data.size()});
512	          }
513	          // Block-store lift (dual of the resume staging): the drain sd/fsd-sweep
514	          // stored x1..x30 / f0..f31 into the scratch page; lift them into the
515	          // drained state. Gated on the SAME fits condition StateDrain used to
516	          // pick sweep-vs-abstract -- when the V page is full it read them via
517	          // Abstract Commands and populated the state directly, so lifting stale
518	          // scratch would clobber correct values. x31 (the GPR sweep base) was
519	          // captured via abstract read inside the drain, so only x1..x30 lift.
520	          const std::span<const uint8_t> ram{platform.main_memory.data.data(),
521	                                             platform.main_memory.data.size()};
522	          if (hybrid::gpr_scratch_fits(state->vlenb))
523	            hybrid::read_gpr_from_scratch(*state, ram, 30);
524	          if ((state->flags & HYBRID_FLAG_FP) != 0u
525	              && hybrid::fpr_scratch_fits(state->vlenb))
526	            hybrid::read_fpr_from_scratch(*state, ram);
527	          // NOTE: no CSR-sweep lift -- the Andes+M-ext drain sweep is disabled
528	          // (see HandoffController::set_block_store_drain); those CSRs drain via
529	          // the abstract-tolerant path into state directly.
530	          spdlog::info("hybrid handoff: drained at pc=0x{:x}, writing {}",
531	                       pc, hybrid_state_path_);
532	          std::ofstream f(hybrid_state_path_, std::ios::binary);
533	          f.write(reinterpret_cast<const char*>(&*state), sizeof(*state));
534	          return hybrid::kExitHandoffToQemu;
535	        }
536	      }
537	      return std::nullopt;
538	    }
539	  }
