2	
3	#include "hybrid/abstract_command.hpp"
4	#include "hybrid/andes_caps.hpp"
5	#include "hybrid/dmi_poll.hpp"
6	#include "hybrid/program_buffer.hpp"
7	#include "hybrid/state_abi.h"
8	#include "hybrid/v_regfile_xfer.hpp"
9	
10	#include <array>
11	#include <cstdint>
12	#include <optional>
13	#include <stdexcept>
14	#include <string>
15	
16	namespace hybrid {
17	
18	struct DmiBus
19	{
20	  virtual ~DmiBus() = default;
21	  virtual void write(uint8_t reg, uint32_t value) = 0;
22	  virtual auto read(uint8_t reg) -> uint32_t = 0;
23	};
24	
25	inline auto read_register_64(DmiBus& bus, uint16_t regno,
26	                             const char* poll_label) -> uint64_t;
27	
28	class ResumeDriver
29	{
30	public:
31	  // data0/data1/abstractcs/command are defined once in abstract_command.hpp;
32	  // dmcontrol/dmstatus are run-control registers specific to this driver.
33	  static constexpr uint8_t kData0      = kDmiData0;
34	  static constexpr uint8_t kData1      = kDmiData1;
35	  static constexpr uint8_t kDmcontrol  = 0x10;
36	  static constexpr uint8_t kDmstatus   = 0x11;
37	  static constexpr uint8_t kAbstractcs = kDmiAbstractcs;
38	  static constexpr uint8_t kCommand    = kDmiCommand;
39	
40	  static constexpr uint16_t kCsrDpc      = 0x7B1;
41	  static constexpr uint16_t kCsrDcsr     = 0x7B0;
42	  static constexpr uint16_t kCsrPmpcfg0  = 0x3A0;
43	  static constexpr uint16_t kCsrPmpaddr0 = 0x3B0;
44	  static constexpr uint16_t kCsrFcsr     = 0x003;
45	  static constexpr uint16_t kCsrMstatus  = 0x300;
46	  static constexpr uint16_t kCsrMisa     = 0x301;
47	  static constexpr uint16_t kCsrMedeleg  = 0x302;
48	  static constexpr uint16_t kCsrMideleg  = 0x303;
49	  static constexpr uint16_t kCsrMie      = 0x304;
50	  static constexpr uint16_t kCsrMtvec    = 0x305;
51	  static constexpr uint16_t kCsrMscratch = 0x340;
52	  static constexpr uint16_t kCsrMepc     = 0x341;
53	  static constexpr uint16_t kCsrMcause   = 0x342;
54	  static constexpr uint16_t kCsrMtval    = 0x343;
55	  static constexpr uint16_t kCsrMip      = 0x344;
56	  static constexpr uint16_t kCsrSatp     = 0x180;
57	  static constexpr uint16_t kCsrMcycle   = 0xB00;
58	  static constexpr uint16_t kCsrMinstret = 0xB02;
59	  // Andes machine setup CSRs crt0 writes at boot (see hybrid_state_v1):
60	  // mcache_ctl enables the L1 I/D caches, mmisc_ctl holds misc machine config.
61	  static constexpr uint16_t kCsrMcacheCtl = 0x7CA;
62	  static constexpr uint16_t kCsrMmiscCtl  = 0x7D0;
63	  static constexpr uint16_t kCsrVlenb    = 0xC22;
64	  static constexpr uint16_t kCsrVstart   = 0x008;
65	  static constexpr uint16_t kCsrVxsat    = 0x009;
66	  static constexpr uint16_t kCsrVxrm     = 0x00A;
67	  static constexpr uint16_t kCsrVcsr     = 0x00F;
68	  static constexpr uint16_t kCsrVtype    = 0xC21;
69	  static constexpr uint16_t kCsrVl       = 0xC20;
70	
71	  static constexpr uint32_t kDmcontrolDmactive  = 1u << 0;
72	  static constexpr uint32_t kDmcontrolResumereq = 1u << 30;
73	  static constexpr uint32_t kDmcontrolHaltreq   = 1u << 31;
74	
75	  static constexpr uint32_t kDmstatusAllhalted    = 1u << 9;
76	  static constexpr uint32_t kDmstatusAllresumeack = 1u << 17;
77	
78	  static constexpr uint32_t kAbstractcsBusy        = hybrid::kAbstractcsBusy;
79	  static constexpr uint32_t kAbstractcsCmderrMask  = hybrid::kAbstractcsCmderrMask;
80	
81	  // mstatus extension-state fields: FS (bits 14:13), VS (bits 10:9).
82	  // "Initial" (01) is the minimal enable the abstract FPR / V writes require.
83	  static constexpr uint64_t kMstatusFsMask    = 0x6000ULL;
84	  static constexpr uint64_t kMstatusFsInitial = 0x2000ULL;
85	  static constexpr uint64_t kMstatusVsMask    = 0x600ULL;
86	  static constexpr uint64_t kMstatusVsInitial = 0x200ULL;
87	
88	  static constexpr unsigned kPollIterations = kDmiPollIterations;
89	
90	  // scratch_gpa: the GUEST address of the V-register transport page (L26:
91	  // v_scratch_gpa(ram_base, ram_size) = the mmap's top page). Defaults to the
92	  // "unset" sentinel; a non-V resume never reads it, but a V resume with the
93	  // GPA still unset throws in the sweep (no silent transport via a bogus
94	  // address). The simulator passes the real value from platform.main_memory.
95	  // caps: which Andes custom CSRs the TARGET core implements (derived from its
96	  // config.inc, supplied by the sim binary). Defaults to all() -- transport
97	  // every CSR, the prior behavior -- so existing call sites are unchanged.
98	  explicit ResumeDriver(DmiBus& bus, uint64_t scratch_gpa = kVScratchGpaUnset,
99	                        AndesCaps caps = AndesCaps::all())
100	      : bus_{bus}, scratch_gpa_{scratch_gpa}, caps_{caps}
101	  {}
102	
103	  // Opt-in GPR block-load (prototype): reload x1..x31 with a Program-Buffer
104	  // ld-sweep from the scratch page instead of 31 abstract register writes.
105	  // Off by default so existing callers/tests are unchanged; the simulator
106	  // enables it and stages the values via stage_gpr_to_scratch.
107	  void set_gpr_block_load(bool on) { gpr_block_load_ = on; }
108	
109	  // Opt-in FPR block-load (prototype): reload f0..f31 with a Program-Buffer
110	  // fld-sweep from the scratch page instead of 32 abstract register writes.
111	  // Off by default so existing callers/tests are unchanged; the simulator
112	  // enables it and stages the values via stage_fpr_to_scratch.
113	  void set_fpr_block_load(bool on) { fpr_block_load_ = on; }
114	
115	  // Opt-in Andes+M-ext CSR sweep: restore the caps-supported CSR block with a
116	  // Program-Buffer ld+csrrw sweep from the CSR scratch page instead of one
117	  // abstract write per CSR. Off by default; the simulator enables it and stages
118	  // the values via stage_csr_to_scratch. Shares the flag name with StateDrain.
119	  void set_csr_sweep(bool on) { csr_sweep_ = on; }
120	
121	  void resume(const hybrid_state_v1& state)
122	  {
123	    if (state.magic != HYBRID_STATE_MAGIC)
124	      throw std::runtime_error("ResumeDriver::resume: bad magic");
125	    if (state.version != HYBRID_STATE_VERSION)
126	      throw std::runtime_error("ResumeDriver::resume: unsupported version");
127	    // L6: only U(0)/S(1)/M(3) fit dcsr.prv; 2 is the reserved encoding.
128	    if (state.priv == 2 || state.priv > 3)
129	      throw std::runtime_error("ResumeDriver::resume: invalid privilege");
130	
131	    // dmactive must transition 0->1 in its own write before any other
132	    // DMCONTROL bit is honored (RISC-V Debug Spec).
133	    bus_.write(kDmcontrol, kDmcontrolDmactive);
134	    request_halt();
135	    poll_until_set(bus_, kDmstatus, kDmstatusAllhalted, "ResumeDriver halt");
136	
137	    // mstatus: enable FS / VS so the following FPR / V abstract writes are
138	    // accepted (FS or VS == Off disables the extension and the hart NACKs
139	    // the writes). The drained state.mstatus may legitimately carry FS or
140	    // VS at Off (e.g. an OS context-switched the regs away before the
141	    // trigger fired) -- gating the write on the drained field skips the
142	    // enable and silently NACKs every subsequent FPR / V-CSR write. Always
143	    // write mstatus when either extension is in scope; force-OR Initial
144	    // when the drained field is Off. This enable is local to the vsim
145	    // phase; the state.mstatus written to the handoff file is left
146	    // unmodified.
147	    if (state.flags & (HYBRID_FLAG_FP | HYBRID_FLAG_V)) {
148	      uint64_t enable_mstatus = state.mstatus;
149	      if ((state.flags & HYBRID_FLAG_FP) && (enable_mstatus & kMstatusFsMask) == 0)
150	        enable_mstatus |= kMstatusFsInitial;  // FS = Initial
151	      if ((state.flags & HYBRID_FLAG_V)  && (enable_mstatus & kMstatusVsMask) == 0)
152	        enable_mstatus |= kMstatusVsInitial;  // VS = Initial
153	      write_csr_abstract_or_pb(kCsrMstatus, enable_mstatus);
154	    }
155	
156	    // FPR restore (requires mstatus.FS enabled above). The block-load (opt-in)
157	    // sweeps f0..f31 from the scratch page via a PB fld-sweep -- ~6 halted-hart
158	    // round-trips instead of 32 abstract writes -- when the V region leaves room;
159	    // otherwise fall back to per-register abstract writes. Its integer base x5 is
160	    // re-staged by the V sweep and restored by the GPR loop below, so it is safe
161	    // to clobber here.
162	    if (state.flags & HYBRID_FLAG_FP) {
163	      if (fpr_block_load_ && scratch_gpa_ != kVScratchGpaUnset
164	          && fpr_scratch_fits(state.vlenb)) {
165	        restore_fprs_via_pb(fpr_scratch_gpa(scratch_gpa_));
166	      } else {
167	        for (uint16_t i = 0; i < 32; ++i)
168	          write_64bit_register(regno_fpr(i), state.fpr[i]);
169	      }
170	      // L20: fcsr (frm + sticky fflags). Same FS gate as the FPRs; PB
171	      // fallback scratch x5 is overwritten by the GPR loop below.
172	      write_csr_abstract_or_pb(kCsrFcsr, state.fcsr);
173	    }
174	
175	    // Tier-A V CSR restore (before GPRs: PB fallback uses x5 as scratch;
176	    // the GPR loop overwrites x5 afterward so state is preserved).
177	    if (state.flags & HYBRID_FLAG_V) {
178	      // V data regfile: reload v0..v31 from the shared scratch region via the
179	      // Program Buffer. Runs BEFORE the architectural V-CSR restore below
180	      // because the sweep's own vsetvl (e8/m8) clobbers vtype/vl/vstart, which
181	      // the restore then overwrites with the architectural values. The sweep
182	      // uses x5/x6/x7 as scratch (x7 is the group base pointer); the GPR loop
183	      // below restores all three. The scratch is vlenb-packed
184	      // (stage_v_to_scratch), so the sweep takes only the runtime vlenb.
185	      if (scratch_gpa_ == kVScratchGpaUnset)
186	        throw std::runtime_error(
187	          "ResumeDriver::resume: V state present but scratch GPA unset");
188	      pb_v_data_sweep(bus_, scratch_gpa_, state.vlenb, /*load=*/true);
189	
190	      // Tier-B: vtype+vl via vsetvl x0,x5,x6 in PB.
191	      // Direct csrrw to vtype sets vill; vl is read-only. Stage operands in
192	      // scratch GPRs x5(vl) and x6(vtype) then let vsetvl set both atomically.
193	      // x5/x6 are overwritten by the GPR loop below, so no leakage.
194	      write_64bit_register(regno_gpr(5), state.vl);
195	      write_64bit_register(regno_gpr(6), state.vtype);
196	      const std::array<uint32_t, 1> pb_vsetvl = { encode_vsetvl(0, 5, 6) };
197	      exec_progbuf(bus_, std::span<const uint32_t>{pb_vsetvl});
198	      // vstart must come AFTER vsetvl: vsetvl resets vstart to 0.
199	      write_csr_abstract_or_pb(kCsrVstart, state.vstart);
200	      write_csr_abstract_or_pb(kCsrVxsat,  state.vxsat);
201	      write_csr_abstract_or_pb(kCsrVxrm,   state.vxrm);
202	      write_csr_abstract_or_pb(kCsrVcsr,   state.vcsr);
203	    }
204	
205	    // L6: dret resumes into dcsr.prv, which is M after the boot halt. For an
206	    // S/U-mode handoff, read-modify-write the prv field so the ROI executes
207	    // in the drained privilege; M-mode states skip the write (prv already 3).
208	    // Before the GPR loop: a PB fallback would clobber scratch x5.
209	    if (state.priv != 3) {
210	      // L2 slice: with PMP implemented and no matching entry, every S/U
211	      // access faults (priv spec v1.10) -- mirror the producer's PMP block
212	      // so the ROI can fetch at all. All pmpaddr before any pmpcfg (a locked
213	      // cfg discards later addr writes); odd pmpcfg CSRs do not exist on
214	      // RV64. Tolerant writes: entries beyond what the hart implements
215	      // mirror as no-ops. M-mode handoffs keep PMP pass-through-only (L2).
216	      for (uint16_t i = 0; i < HYBRID_PMP_ADDR_NUM; ++i)
217	        write_csr_tolerant(kCsrPmpaddr0 + i, state.pmpaddr[i]);
218	      for (uint16_t i = 0; i < HYBRID_PMP_CFG_NUM; i += 2)
219	        write_csr_tolerant(kCsrPmpcfg0 + i, state.pmpcfg[i]);
220	
221	      const uint64_t dcsr =
222	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr");
223	      write_csr_abstract_or_pb(kCsrDcsr,
224	                               (dcsr & ~uint64_t{0x3}) | state.priv);
225	      // An M-only core WARL-pins dcsr.prv to 3; resuming anyway would
226	      // silently measure the ROI in the wrong privilege. Verify and abort.
227	      const uint64_t got =
228	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr verify")
229	        & 0x3u;
230	      if (got != state.priv)
231	        throw std::runtime_error(
232	          "ResumeDriver::resume: engine does not implement privilege level "
233	          + std::to_string(state.priv)
234	          + " (dcsr.prv pinned to " + std::to_string(got)
235	          + "); pick an S/U-capable engine");
236	    }
237	
238	    // Andes V5 + M-ext CSR restore. Runs BEFORE the GPR loop so the csr_sweep
239	    // may use x5/x6 as scratch (the GPR loop restores them after, exactly like
240	    // the FPR and V restores above). See restore_andes_m_ext.
241	    restore_andes_m_ext(state);
242	
243	    // GPRs + DPC (after V CSRs so PB scratch x5 is safe to overwrite). The
244	    // block-load (opt-in) sweeps x1..x31 from the scratch page via the Program
245	    // Buffer -- ~4 DM round-trips instead of 31 abstract writes -- when the V
246	    // region leaves room; otherwise fall back to per-register abstract writes.
247	    if (gpr_block_load_ && scratch_gpa_ != kVScratchGpaUnset
248	        && gpr_scratch_fits(state.vlenb)) {
249	      restore_gprs_via_pb(gpr_scratch_gpa(scratch_gpa_));
250	    } else {
251	      for (uint16_t i = 1; i < 32; ++i)
252	        write_64bit_register(regno_gpr(i), state.gpr[i]);
253	    }
254	    write_64bit_register(regno_csr(kCsrDpc), state.pc);
255	
256	    write_csr_tolerant(kCsrMtvec, state.mtvec);
257	
258	    // L23: mscratch is the M-mode software scratch CSR -- a pure read/write
259	    // register with no hardware side effects, legal to use inside a trap-free
260	    // ROI. Restore it so a value stashed before the handoff survives into the
261	    // vsim phase.
262	    write_csr_tolerant(kCsrMscratch, state.mscratch);
263	
264	    // L24: the writable M-mode trap/interrupt CSRs. In the trap-free,
265	    // interrupt-free ROI envelope these are ordinary read/write registers, so a
266	    // value stashed before the handoff must survive into the vsim phase (same
267	    // round-trip as mscratch). Tolerant writes: a WARL / read-only field (mip's
268	    // hardware-driven pending bits, or mtval on a core that hardwires it)
269	    // mirrors as a no-op. medeleg/mideleg/satp stay unrestored -- they are
270	    // S-mode CSRs the M-only default engine does not implement (L3/L4).
271	    write_csr_tolerant(kCsrMepc,   state.mepc);
272	    write_csr_tolerant(kCsrMcause, state.mcause);
273	    write_csr_tolerant(kCsrMtval,  state.mtval);
274	    write_csr_tolerant(kCsrMie,    state.mie);
275	    write_csr_tolerant(kCsrMip,    state.mip);
276	
277	    // Andes cache fix: restore the machine setup CSRs crt0 wrote at boot. The
278	    // functional engine ran crt0 (where `csrw mcache_ctl` enables the L1 I/D
279	    // caches) but has no cache model, so without this the cycle engine resumes
280	    // at the ROI with caches at their reset default -- DISABLED -- and the
281	    // whole measured window runs uncached, inflating it severalfold. Tolerant
282	    // writes: an engine without these custom CSRs (e.g. non-Andes) mirrors the
283	    // write as a no-op, and a drained 0 (caches were off) restores the reset
284	    // state, so this is always safe to issue.
285	    write_csr_tolerant(kCsrMcacheCtl, state.mcache_ctl);
286	    write_csr_tolerant(kCsrMmiscCtl,  state.mmisc_ctl);
287	
288	    // F-T2.4: restore mcycle/minstret so the vsim phase continues counting
289	    // from QEMU1's drain value. Without this, vsim's local counter starts
290	    // at zero, so the drained mcycle delta (vsim minus QEMU 1) would no
291	    // longer measure the ROI. PB fallback uses x5 as scratch; safe to
292	    // overwrite here as the GPR loop already ran.
293	    write_csr_abstract_or_pb(kCsrMcycle,   state.mcycle);
294	    write_csr_abstract_or_pb(kCsrMinstret, state.minstret);
295	
296	    clear_cmderr_if_set();
297	    request_resume();
298	    poll_until_set(bus_, kDmstatus, kDmstatusAllresumeack,
299	                   "ResumeDriver resume");
300	  }
301	
302	private:
303	  void request_halt()
304	  {
305	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolHaltreq);
306	  }
307	
308	  void request_resume()
309	  {
310	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolResumereq);
311	  }
312	
313	  void write_64bit_register(uint16_t regno, uint64_t value)
314	  {
315	    write_register_abstract(bus_, regno, value);
316	  }
317	
318	  // GPR block-load: reload x1..x31 from the scratch page via a PB ld-sweep. Base
319	  // x31 rides the sweep last (it is the base pointer). x31's slot is the
320	  // mapping's final word, which the memory decoder now returns correctly.
321	  void restore_gprs_via_pb(uint64_t gpr_gpa)
322	  {
323	    pb_block_sweep(bus_, 31, gpr_gpa, 1, 32, &encode_ld);
324	  }
325	
326	  // FPR block-load: reload f0..f31 from the scratch page via a PB fld-sweep,
327	  // integer base x5 (a caller-saved scratch the GPR loop restores later). No
328	  // f-reg is the base, so all 32 ride the sweep (first_reg = 0).
329	  void restore_fprs_via_pb(uint64_t fpr_gpa)
330	  {
331	    pb_block_sweep(bus_, 5, fpr_gpa, 0, 32, &encode_fld);
332	  }
333	
334	  // Andes V5 + M-ext CSR restore. When the sweep is enabled and the V region
335	  // leaves room, batch every caps-supported CSR from the CSR scratch page via a
336	  // Program-Buffer ld+csrrw sweep (~3 CSRs per DM round-trip; base x6 / value x5,
337	  // both restored by the GPR loop that runs after). Else fall back to one
338	  // caps-gated abstract write per CSR. The scratch was packed in
339	  // for_each_sweep_csr order by stage_csr_to_scratch, so the sweep's addr list
340	  // uses that same walk. Absent CSRs are never in the list (caps-gated), so no
341	  // csrrw faults -- a fault would mean the caps map is wrong (a config bug).
342	  void restore_andes_m_ext(const hybrid_state_v1& state)
343	  {
344	    const bool andes = state.flags & HYBRID_FLAG_ANDES;
345	    const bool mext  = state.flags & HYBRID_FLAG_M_EXT;
346	    if (!andes && !mext) return;
347	
348	    if (csr_sweep_ && scratch_gpa_ != kVScratchGpaUnset
349	        && csr_scratch_fits(state.vlenb)) {
350	      std::array<uint16_t, kCsrScratchSlots> addrs{};
351	      std::size_t n = 0;
352	      for_each_sweep_csr(state, caps_,
353	        [&](std::size_t i, uint16_t addr, const uint64_t&) {
354	          addrs[i] = addr; n = i + 1;
355	        });
356	      csr_sweep(bus_, /*base=*/6, csr_scratch_gpa(scratch_gpa_), /*val=*/5,
357	                std::span<const uint16_t>{addrs.data(), n}, CsrSweepDir::Restore);
358	      return;
359	    }
360	
361	    // Fallback: one caps-gated abstract write per CSR (pmaaddr before pmacfg,
362	    // mirroring the PMP restore ordering).
363	    if (andes) {
364	#define X(field, addr, name) \
365	  if (caps_.supports_csr(addr)) write_csr_tolerant(addr, state.andes.field);
366	      HYBRID_ANDES_CSR_LIST(X)
367	#undef X
368	      for (uint16_t i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
369	        if (caps_.supports_csr(HYBRID_PMA_ADDR0_CSR + i))
370	          write_csr_tolerant(HYBRID_PMA_ADDR0_CSR + i, state.andes.pmaaddr[i]);
371	      for (uint16_t i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
372	        if (caps_.supports_csr(HYBRID_PMA_CFG0_CSR + 2 * i))
373	          write_csr_tolerant(HYBRID_PMA_CFG0_CSR + 2 * i, state.andes.pmacfg[i]);
374	    }
375	    if (mext) {
376	#define X(field, addr, name) \
377	  if (caps_.supports_csr(addr)) write_csr_tolerant(addr, state.m_ext.field);
378	      HYBRID_M_EXT_CSR_LIST(X)
379	#undef X
380	    }
381	  }
382	
383	  // Abstract-first CSR write with Program Buffer fallback.
384	  // Tries an abstract register write; if the DM signals cmderr, clears it,
385	  // stages the value in scratch_gpr via abstract GPR write, then executes a
386	  // one-instruction PB (`csrrw x0, csr, scratch_gpr`).  scratch_gpr defaults
387	  // to x5 (t0) which the GPR restore loop overwrites later.
388	  void write_csr_abstract_or_pb(uint16_t csr, uint64_t value,
389	                                 uint8_t scratch_gpr = 5)
390	  {
391	    write_64bit_register(regno_csr(csr), value);
392	    if ((bus_.read(kAbstractcs) & kAbstractcsCmderrMask) == 0u) return;
393	    bus_.write(kAbstractcs, kAbstractcsCmderrMask);  // W1C: clear sticky error
394	    write_64bit_register(regno_gpr(scratch_gpr), value);
395	    const std::array<uint32_t, 1> pb = { encode_csrrw(0, csr, scratch_gpr) };
396	    exec_progbuf(bus_, std::span<const uint32_t>{pb});
397	  }
398	
399	  // Write a CSR-addressable register and clear any cmderr the DM raised.
400	  // Used for CSRs whose abstract-access support may be implementation
401	  // dependent; a missing CSR mirrors as a no-op rather than blocking the
402	  // remaining writes.
403	  void write_csr_tolerant(uint16_t csr, uint64_t value)
404	  {
405	    write_64bit_register(regno_csr(csr), value);
406	    clear_cmderr_if_set();
407	  }
408	
409	  // abstractcs.cmderr is sticky per the Debug Spec - a subsequent command
410	  // is rejected until the bits are W1C-cleared. We tolerate per-register
411	  // failures (e.g. unimplemented FPR/CSR Abstract access) by clearing the
412	  // error before resuming so the hart isn't left in a stuck state.
413	  // B17: record the last observed non-zero cmderr and a clear count so a
414	  // partially-broken restore is observable via the public accessors
415	  // instead of silently swallowed.
416	  void clear_cmderr_if_set()
417	  {
418	    const auto status = bus_.read(kAbstractcs);
419	    const auto code = (status & kAbstractcsCmderrMask) >> 8;
420	    if (code != 0u) {
421	      last_observed_cmderr_ = code;
422	      ++cmderr_clear_count_;
423	      bus_.write(kAbstractcs, kAbstractcsCmderrMask);
424	    }
425	  }
426	
427	  DmiBus& bus_;
428	  uint64_t scratch_gpa_ = kVScratchGpaUnset;  // L26: V transport page GPA
429	  AndesCaps caps_ = AndesCaps::all();         // target core's Andes-CSR support
430	  bool gpr_block_load_ = false;               // opt-in GPR PB ld-sweep
431	  bool fpr_block_load_ = false;               // opt-in FPR PB fld-sweep
432	  bool csr_sweep_      = false;               // opt-in Andes+M-ext PB csr sweep
433	  uint32_t last_observed_cmderr_ = 0;
434	  uint64_t cmderr_clear_count_   = 0;
435	
436	public:
437	  // B17: diagnostic side channel. Non-zero last_observed_cmderr() means
438	  // at least one abstract write tripped a sticky cmderr the restore
439	  // tolerated by clearing. cmderr_clear_count() is the total number of
440	  // such clears across all calls into clear_cmderr_if_set() this run.
441	  auto last_observed_cmderr() const -> uint32_t { return last_observed_cmderr_; }
442	  auto cmderr_clear_count() const -> uint64_t   { return cmderr_clear_count_; }
443	};
444	
445	// Read a 64-bit hart register (GPR / FPR / CSR by abstract regno) over DMI
446	// via an Abstract Command. Halts-and-reads contract: caller must have the
447	// hart in the halted state. Shared by StateDrain (drain at exit). If
448	// abstractcs.cmderr goes sticky after the command, the helper clears it and
449	// reports 0 rather than blocking the caller -- a missing CSR mirrors as zero
450	// instead of corrupting the adjacent field.
451	inline auto read_register_64_checked(DmiBus& bus, uint16_t regno,
452	                                     const char* poll_label
453	                                       = "read_register_64")
454	  -> std::optional<uint64_t>
455	{
456	  using RD = ResumeDriver;
457	  bus.write(RD::kCommand,
458	            access_register_command(regno, AarSize::Bits64, /*write=*/false));
459	  poll_until_clear(bus, RD::kAbstractcs, RD::kAbstractcsBusy, poll_label);
460	  const auto status = bus.read(RD::kAbstractcs);
461	  if ((status & RD::kAbstractcsCmderrMask) != 0u) {
462	    bus.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
463	    return std::nullopt;
464	  }
465	  const uint64_t lo = bus.read(RD::kData0);
466	  const uint64_t hi = bus.read(RD::kData1);
467	  return lo | (hi << 32);
468	}
469	
470	inline auto read_register_64(DmiBus& bus, uint16_t regno,
471	                             const char* poll_label = "read_register_64")
472	  -> uint64_t
473	{
474	  return read_register_64_checked(bus, regno, poll_label).value_or(0u);
475	}
476	
477	}  // namespace hybrid
