TEST_CASE("LG2: the V-data sweep clobbers vtype/vl, so the architectural "
          "vsetvl still runs when the sweep ran -- even with baseline-equal "
          "vtype/vl -- and vstart is rewritten after it")
{
  auto s = rv64_state(0x80001000, 0);
  s.flags |= HYBRID_FLAG_V;
  s.vlenb = 64;
  s.vtype = 0x8000000000000000ull;
  s.vl = 0;
  const hybrid_state_v1 baseline = s;
  s.vreg[5] = 0x77;  // one live byte -> the data sweep must run

  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);
  hybrid::ResumeDriver driver(bus, kScratch);
  driver.set_reset_baseline(baseline);
  driver.resume(s);

  // Architectural vsetvl evidence: x6 staged with state.vtype (0x8000...0,
  // distinct from the sweep's own kVtypeE8M8 staging of x6).
  bool found_x6_vtype = false;
  for (std::size_t i = 2; i < bus.ops.size(); ++i) {
    const auto& op = bus.ops[i];
    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
        && (op.value & 0xFFFFu) == hybrid::regno_gpr(6)
        && ((op.value >> 16) & 1u)) {
      const auto& d0 = bus.ops[i - 2];
      const auto& d1 = bus.ops[i - 1];
      if (d0.reg == kData0 && d0.value == uint32_t(s.vtype & 0xFFFFFFFFu)
          && d1.reg == kData1 && d1.value == uint32_t(s.vtype >> 32))
        found_x6_vtype = true;
    }
  }
  CHECK(found_x6_vtype);
  // vstart was reset to 0 by that vsetvl, so it must be rewritten too.
  CHECK(contains_regno(cmd_regnos(bus.ops), hybrid::regno_csr(0x008)));
}

