TEST_CASE("LG3: a baseline captured this run (v_cfg_at_reset=false) forces "
          "vsetvl + vstart even when fully baseline-equal -- the capture "
          "drain's V dump sweep already clobbered vtype/vl/vstart")
{
  auto s = rv64_state(0x80001000, 0);
  s.flags |= HYBRID_FLAG_V;
  s.vlenb = 64;
  s.vtype = 0x8000000000000000ull;
  s.vl = 0;
  const hybrid_state_v1 baseline = s;

  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);
  hybrid::ResumeDriver driver(bus, kScratch);
  driver.set_reset_baseline(baseline, /*v_cfg_at_reset=*/false);
  driver.resume(s);

  // The architectural vsetvl still fires (only possible PB user here: the
  // data sweep stays elided, so any PB exec is the vsetvl)...
  bool pb_exec = false;
  for (const auto& op : bus.ops)
    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
        && op.value == hybrid::kExecProgbufCmd)
      pb_exec = true;
  CHECK(pb_exec);
  // ...and vstart is rewritten after it.
  CHECK(contains_regno(cmd_regnos(bus.ops), hybrid::regno_csr(0x008)));
  // The v-data elision is unaffected: 32 vregs + vxsat/vxrm/vcsr + 9 scalars.
  CHECK(driver.baseline_skip_count() == 32u + 3u + 9u);
}

