1	// Andes-CSR capability gating. A core implements only the Andes CSRs its
2	// config.inc enables; restoring a CSR the core lacks can hang the DMI
3	// handshake (observed on ax45mpv_premium: ucode + mecc_code). So the
4	// resume/drain loops transport only the CSRs the target core supports. This
5	// pins the CSR-address -> feature-gate map and the premium subset.
6	#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
7	#include "doctest.h"
8	
9	#include "hybrid/andes_caps.hpp"
10	#include "hybrid/state_abi.h"
11	
12	#include <algorithm>
13	#include <string>
14	#include <vector>
15	
16	using hybrid::AndesCaps;
17	using hybrid::AndesGate;
18	
19	// ax45mpv_premium config.inc: CoDense + ILM + DLM on; DSP, ECC, PowerBrake,
20	// StackSafe, performance-monitor, PMA off (matches the empirical probe).
21	static AndesCaps premium()
22	{
23	  AndesCaps c = AndesCaps::none();
24	  c.set(AndesGate::CODENSE);
25	  c.set(AndesGate::ILM);
26	  c.set(AndesGate::DLM);
27	  return c;
28	}
29	
30	TEST_CASE("all() transports every Andes CSR (default = no gating)")
31	{
32	  const AndesCaps c = AndesCaps::all();
33	  CHECK(c.supports_csr(0x801));  // ucode
34	  CHECK(c.supports_csr(0x7C2));  // mecc_code
35	  CHECK(c.supports_csr(0x800));  // uitb
36	}
37	
38	TEST_CASE("premium skips the CSRs its config lacks -- no hang")
39	{
40	  const AndesCaps c = premium();
41	  CHECK_FALSE(c.supports_csr(0x801));  // ucode      (DSP off)  -- the hang case
42	  CHECK_FALSE(c.supports_csr(0x7C2));  // mecc_code  (ECC off)  -- the hang case
43	  CHECK_FALSE(c.supports_csr(0x7C5));  // mpft_ctl   (PowerBrake off)
44	  CHECK_FALSE(c.supports_csr(0x7C6));  // mhsp_ctl   (StackSafe off)
45	  CHECK_FALSE(c.supports_csr(0x7C7));  // msp_bound
46	  CHECK_FALSE(c.supports_csr(0x7C8));  // msp_base
47	  CHECK_FALSE(c.supports_csr(0x7D1));  // mcountermask_m (perf-monitor off)
48	  CHECK_FALSE(c.supports_csr(HYBRID_PMA_ADDR0_CSR));  // pmaaddr0 (PMA off)
49	  CHECK_FALSE(c.supports_csr(HYBRID_PMA_CFG0_CSR));   // pmacfg0
50	}
51	
52	TEST_CASE("premium keeps the CSRs its config has")
53	{
54	  const AndesCaps c = premium();
55	  CHECK(c.supports_csr(0x800));  // uitb     (CoDense on)
56	  CHECK(c.supports_csr(0x017));  // jvt      (CoDense on)
57	  CHECK(c.supports_csr(0x7C0));  // milmb    (ILM on)
58	  CHECK(c.supports_csr(0x7C1));  // mdlmb    (DLM on)
59	  CHECK(c.supports_csr(0x7C4));  // mxstatus (base machine CSR -> ALWAYS)
60	  CHECK(c.supports_csr(0x7DF));  // mclk_ctl (base machine CSR -> ALWAYS)
61	}
62	
63	TEST_CASE("--describe name list reflects the caps")
64	{
65	  const std::vector<std::string> n = hybrid::supported_andes_csr_names(premium());
66	  auto has = [&](const char* s) {
67	    return std::find(n.begin(), n.end(), s) != n.end();
68	  };
69	  CHECK(has("uitb"));
70	  CHECK(has("milmb"));
71	  CHECK_FALSE(has("ucode"));
72	  CHECK_FALSE(has("mecc_code"));
73	
74	  // PMA group markers ("pmacfg"/"pmaaddr") are emitted only when PMA is on, so
75	  // the driver can verify-exclude the whole PMA block on a core that lacks it.
76	  CHECK_FALSE(has("pmacfg"));   // premium: PMA off
77	  CHECK_FALSE(has("pmaaddr"));
78	  const std::vector<std::string> all = hybrid::supported_andes_csr_names(AndesCaps::all());
79	  auto all_has = [&](const char* s) {
80	    return std::find(all.begin(), all.end(), s) != all.end();
81	  };
82	  CHECK(all_has("pmacfg"));
83	  CHECK(all_has("pmaaddr"));
84	}
