        // transports into the drained state (see lift_scratch_blocks).
        lift_scratch_blocks(*state);
        // NOTE: no CSR-sweep lift -- the Andes+M-ext drain sweep is disabled
        // (see HandoffController::set_block_store_drain); those CSRs drain via
        // the abstract-tolerant path into state directly.
